/// <reference types="vite/client" />

/**
 * Переменные окружения, которые читает ядро.
 *
 * Объявлены в `lib/`, а не в панели: читает их ядро, а зависеть от файлов
 * панели оно не может. Свои переменные панель описывает в `src/vite-env.d.ts` —
 * интерфейс тот же, TypeScript сливает объявления.
 *
 * Объявление вообще нужно потому, что `vite/client` описывает `import.meta.env`
 * индексной сигнатурой `any`: без него любое чтение переменной было бы
 * небезопасным по типам, и type-aware правила eslint на нём ругались бы.
 *
 * Каждая переменная необязательная: `.env` может не существовать, и ядро обязано
 * это пережить — подставить запасное значение и предупредить.
 */
interface ImportMetaEnv {
  /** Префикс, который приписывается ко всем путям эндпоинтов. */
  readonly VITE_API_BASE_URL?: string;
  /** Имя панели: `<title>` и подпись у логотипа по умолчанию. */
  readonly VITE_APP_NAME?: string;
  /** Буквы внутри знака логотипа. Без неё — первые буквы слов имени. */
  readonly VITE_APP_ABBR?: string;
  /** Ключ панели у бэкенда — им она представляется при входе. Без неё — аббревиатура строчными. */
  readonly VITE_PANEL_KEY?: string;
}
